import org.apache.commons.cli.OptionBuilder;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.*;

public class OptionBuilderWithLongOptTest {

    private Field longOptionField;
    private Field instanceField;
    private String originalLongOption;
    private Object instanceValue;

    @BeforeEach
    public void setUp() throws Exception {
        // Obtain the private static fields via reflection
        longOptionField = OptionBuilder.class.getDeclaredField("longOption");
        longOptionField.setAccessible(true);

        instanceField = OptionBuilder.class.getDeclaredField("INSTANCE");
        instanceField.setAccessible(true);

        // Save originals to restore after tests
        originalLongOption = (String) longOptionField.get(null);
        instanceValue = instanceField.get(null);
    }

    @AfterEach
    public void tearDown() throws Exception {
        // Restore original static field values to avoid test interference
        longOptionField.set(null, originalLongOption);
    }

    @Test
    public void testWithLongOptSetsFieldAndReturnsInstance() throws Exception {
        String newOpt = "my-long-opt";

        // Call the focal method
        OptionBuilder returned = OptionBuilder.withLongOpt(newOpt);

        // Verify the static field was updated
        String fieldValue = (String) longOptionField.get(null);
        assertEquals(newOpt, fieldValue, "longOption field should be set to the provided value");

        // Verify the returned instance is the same INSTANCE
        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withLongOpt should return the unique INSTANCE");
        assertSame(instanceValue, returned, "returned instance should match the stored INSTANCE value");
    }

    @Test
    public void testWithLongOptAcceptsNullAndReturnsInstance() throws Exception {
        // Set a previous value first to ensure null actually changes it
        longOptionField.set(null, "previous");

        OptionBuilder returned = OptionBuilder.withLongOpt(null);

        // longOption should now be null
        String fieldValue = (String) longOptionField.get(null);
        assertNull(fieldValue, "longOption should be set to null when passing null");

        // Returned instance should still be INSTANCE
        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withLongOpt should return the unique INSTANCE even for null input");
    }

    @Test
    public void testWithLongOptOverridesPreviousValue() throws Exception {
        // Set an initial value
        longOptionField.set(null, "initial");
        assertEquals("initial", longOptionField.get(null));

        // Override with a new value
        OptionBuilder.withLongOpt("overridden");
        assertEquals("overridden", longOptionField.get(null), "longOption should be overridden by subsequent calls");

        // Override again with empty string
        OptionBuilder.withLongOpt("");
        assertEquals("", longOptionField.get(null), "longOption should accept and be set to empty string");
    }
}

